old:
let first = keys.first()?;
if tick <= first.tick {
    return Some(first.value.clone());
}
let last = keys.last()?;
if tick >= last.tick {
    return Some(last.value.clone());
}

new:
let first = keys.first()?;
if tick <= first.tick {
    return interpolate_property_value(&first.value, &first.value, 0.0);
}
let last = keys.last()?;
if tick >= last.tick {
    return interpolate_property_value(&last.value, &last.value, 0.0);
}
